<?php require_once __DIR__.'/app/bootstrap.php';$csrf=csrf_token();?><!doctype html><html><head><meta charset="utf-8"><title>BriteScheduler Sign In</title><style>body{font-family:system-ui;background:#f5f7fb}.box{max-width:360px;margin:10vh auto;background:white;padding:30px;border-radius:12px}input,button{box-sizing:border-box;width:100%;padding:11px;margin:7px 0}</style></head><body><div class="box"><h1>BriteScheduler</h1><form id="f"><input name="email" type="email" placeholder="Email" required><input name="password" type="password" placeholder="Password" required><button>Sign in</button><p id="e"></p></form></div><script>f.onsubmit=async x=>{x.preventDefault();let d=Object.fromEntries(new FormData(f));let r=await fetch(<?=json_encode(app_url('/api/auth/login.php'))?>,{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':<?=json_encode($csrf)?>},body:JSON.stringify(d)}),j=await r.json();if(r.ok)location=j.redirect;else e.textContent=j.error}</script></body></html>